SELECT p.post_id, p.company_code, c.name AS company_name, p.title, m.nickname, (SELECT COUNT(*) FROM comment cm WHERE cm.post_id = p.post_id) AS comment_count, (SELECT COUNT(*) FROM post_file f WHERE f.post_id = p.post_id) AS file_count, p.created_at FROM post p JOIN company c ON c.code = p.company_code JOIN member m ON m.member_id = p.member_id
p.company_code = #{code}
ORDER BY p.post_id DESC LIMIT #{size} OFFSET #{offset}

SELECT post_id, company_code, member_id, title, content, created_at, updated_at
FROM post
WHERE post_id = #{postId}
